<div class="confirm-overlay" id="confirmOverlay">
    <div class="confirm-box">
        <div class="confirm-icon" id="confirmIcon" style="width:80px;height:80px;border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;font-size:2.5rem;background:#fef2f2;border:3px solid #fecaca;">⚠️</div>
        <div class="confirm-title" id="confirmTitle" style="font-weight:900;font-size:1.3rem;margin-bottom:8px;color:#1f2937;">Konfirmasi</div>
        <div class="confirm-message" id="confirmMessage" style="font-size:0.9rem;color:#6b7280;margin-bottom:6px;line-height:1.5;">Apakah Anda yakin?</div>
        <div class="confirm-detail" id="confirmDetail" style="background:#fef2f2;border:1px solid #fecaca;border-radius:12px;padding:12px;margin:16px 0;font-size:0.85rem;color:#991b1b;font-weight:600;display:none;"></div>
        <div style="display:flex;gap:10px;margin-top:20px;">
            <button style="flex:1;padding:14px;border-radius:14px;font-weight:800;cursor:pointer;background:#f3f4f6;color:#374151;border:2px solid #e5e7eb;" onclick="hideConfirm()">Kembali</button>
            <button id="confirmYesBtn" style="flex:1;padding:14px;border-radius:14px;font-weight:800;cursor:pointer;background:#ef4444;color:white;border:none;">Ya</button>
        </div>
    </div>
</div>